    # Defensive access to observation fields
    direction = observation.get('direction', None)
    resources = observation.get('resources', 0)
    positions = observation.get('positions', {})
    own_pos = positions.get('self', (0, 0))
    opponents = positions.get('opponents', [])
    territory_map = observation.get('territory_map', [])

    # Initialize move to no movement
    dx, dy = 0, 0

    # Helper function to get a safe neighbor cell
    def get_neighbor(pos, delta_x, delta_y):
        return (pos[0] + delta_x, pos[1] + delta_y)

    # Priority 1: Collect resources if available nearby
    resource_directions = [(0,1),(1,0),(0,-1),(-1,0)]
    for ndx, ndy in resource_directions:
        neighbor = get_neighbor(own_pos, ndx, ndy)
        if resources > 0:
            # If resource detected nearby, move towards it
            dx, dy = ndx, ndy
            return [dx, dy]

    # Priority 2: Pursue nearest opponent
    if opponents:
        # Choose opponent with minimal Manhattan distance
        def dist(p): return abs(p[0] - own_pos[0]) + abs(p[1] - own_pos[1])
        target = min(opponents, key=dist)
        delta_x = target[0] - own_pos[0]
        delta_y = target[1] - own_pos[1]
        # Simplify move to one step towards opponent
        if abs(delta_x) > abs(delta_y):
            dx = 1 if delta_x > 0 else -1
            dy = 0
        elif delta_y != 0:
            dx = 0
            dy = 1 if delta_y > 0 else -1
        else:
            dx, dy = 0, 0
        return [dx, dy]

    # Priority 3: Expand into unexplored territory
    # Check surrounding cells for unclaimed territory (represented as None or 0)
    for ndx, ndy in resource_directions:
        neighbor = get_neighbor(own_pos, ndx, ndy)
        # Defensive check for territory map bounds
        if territory_map:
            x, y = neighbor
            if 0 <= x < len(territory_map) and 0 <= y < len(territory_map[0]):
                if territory_map[x][y] in (None, 0):
                    dx, dy = ndx, ndy
                    return [dx, dy]

    # Default: stay in place
    return [0, 0]


